"use client";

import React, { useState, useMemo } from "react";
import { 
  CalendarDays, MapPin, Filter, ChevronDown, 
  Globe, Sparkles, X, Check 
} from "lucide-react";

/* --- 1. DATASET --- */
const HOLIDAYS_DB = [
  // 2025
  { id: 1, name: "New Year's Day", date: "Jan 01", day: "Wed", year: "2025", type: "Public", country: "Global", region: "All" },
  { id: 2, name: "Republic Day", date: "Jan 26", day: "Sun", year: "2025", type: "National", country: "India", region: "All" },
  { id: 3, name: "Presidents' Day", date: "Feb 17", day: "Mon", year: "2025", type: "Public", country: "USA", region: "All" },
  { id: 4, name: "Holi", date: "Mar 14", day: "Fri", year: "2025", type: "Optional", country: "India", region: "North India" },
  { id: 5, name: "Good Friday", date: "Apr 18", day: "Fri", year: "2025", type: "Public", country: "Global", region: "All" },
  
  // 2026
  { id: 6, name: "New Year's Day", date: "Jan 01", day: "Thu", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 7, name: "Republic Day", date: "Jan 26", day: "Mon", year: "2026", type: "National", country: "India", region: "All" },
  { id: 8, name: "Ugadi", date: "Mar 19", day: "Thu", year: "2026", type: "Optional", country: "India", region: "Telangana" },
  { id: 9, name: "Memorial Day", date: "May 25", day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },
  { id: 10, name: "Kannada Rajyotsava", date: "Nov 01", day: "Sun", year: "2026", type: "Optional", country: "India", region: "Karnataka" },
  { id: 11, name: "Christmas", date: "Dec 25", day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
];

/* --- 2. LOCATION MAPPING FOR DEPENDENT FILTERS --- */
const REGIONS_BY_COUNTRY: any = {
    "All": ["All", "Telangana", "Karnataka", "North India"],
    "India": ["All", "Telangana", "Karnataka", "North India"],
    "USA": ["All", "New York", "California"], // Example states
    "Global": ["All"]
};

export default function CompactHolidayList() {
  // --- STATE ---
  const [year, setYear] = useState("2026");
  const [country, setCountry] = useState("All");
  const [region, setRegion] = useState("All");
  const [type, setType] = useState("All");

  // --- SMART FILTER LOGIC ---
  const filteredData = useMemo(() => {
    return HOLIDAYS_DB.filter((h) => {
      const matchYear = h.year === year;
      // Country: Match specific, 'All', or 'Global' holidays
      const matchCountry = country === "All" || h.country === country || h.country === "Global";
      // Region: Match specific, 'All', or holidays that apply to entire country ('All')
      const matchRegion = region === "All" || h.region === region || h.region === "All";
      const matchType = type === "All" || h.type === type;

      return matchYear && matchCountry && matchRegion && matchType;
    });
  }, [year, country, region, type]);

  // --- RESET HANDLER ---
  const handleCountryChange = (newCountry: string) => {
      setCountry(newCountry);
      setRegion("All"); // Reset region when country changes
  };

  return (
    <div className="min-h-screen bg-[#F8F9FC] dark:bg-[#030712] text-slate-900 dark:text-slate-100 font-sans p-6 lg:p-10">
      
      {/* --- 1. COMPACT HEADER & FILTERS --- */}
      <div className="max-w-6xl mx-auto mb-8">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end gap-4 border-b border-slate-200 dark:border-slate-800 pb-6">
            
            {/* Title Block */}
            <div>
                <h1 className="text-2xl font-black uppercase tracking-tight text-slate-900 dark:text-white flex items-center gap-3">
                    Holiday Calendar <span className="bg-slate-100 dark:bg-white/10 text-slate-500 text-[10px] px-2 py-1 rounded-md tracking-widest">{year}</span>
                </h1>
                <p className="text-xs font-medium text-slate-400 mt-1">
                    Showing <span className="text-slate-900 dark:text-white font-bold">{filteredData.length}</span> events for {country === 'All' ? 'Global Operations' : country}
                </p>
            </div>

            {/* Compact Filter Bar */}
            <div className="flex flex-wrap gap-2 w-full lg:w-auto">
                <CompactSelect 
                    label="Year" 
                    value={year} 
                    onChange={setYear} 
                    options={['2025', '2026']} 
                    icon={<CalendarDays size={13} />}
                />
                
                <CompactSelect 
                    label="Country" 
                    value={country} 
                    onChange={handleCountryChange} 
                    options={['All', 'India', 'USA']} 
                    icon={<Globe size={13} />}
                />

                {/* Dependent Region Filter */}
                <CompactSelect 
                    label="Location" 
                    value={region} 
                    onChange={setRegion} 
                    options={REGIONS_BY_COUNTRY[country] || ['All']} 
                    disabled={country === 'Global'}
                    icon={<MapPin size={13} />}
                />

                <div className="bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-lg p-1 flex items-center h-[38px]">
                    {['All', 'Public', 'Optional'].map(t => (
                        <button
                            key={t}
                            onClick={() => setType(t)}
                            className={`px-3 h-full rounded-md text-[9px] font-black uppercase tracking-widest transition-all ${
                                type === t 
                                ? "bg-slate-900 text-white dark:bg-brand-600" 
                                : "text-slate-400 hover:text-slate-900 dark:hover:text-slate-200"
                            }`}
                        >
                            {t}
                        </button>
                    ))}
                </div>
            </div>
          </div>
      </div>

      {/* --- 2. COMPACT GRID (3-Column) --- */}
      <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredData.length > 0 ? filteredData.map((h) => (
            <div 
                key={h.id} 
                className="bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-xl p-4 flex items-center gap-4 hover:border-brand-500/40 transition-all hover:shadow-md group"
            >
                {/* Date Box (Small) */}
                <div className="flex-shrink-0 w-12 h-12 bg-slate-50 dark:bg-white/5 rounded-lg flex flex-col items-center justify-center border border-slate-100 dark:border-white/5 group-hover:bg-brand-50 dark:group-hover:bg-brand-500/10 transition-colors">
                    <span className="text-[8px] font-black uppercase text-slate-400">{h.date.split(' ')[0]}</span>
                    <span className="text-sm font-black text-slate-900 dark:text-white">{h.date.split(' ')[1]}</span>
                </div>

                {/* Info */}
                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                        <span className={`w-1.5 h-1.5 rounded-full ${h.type === 'Optional' ? 'bg-amber-500' : 'bg-emerald-500'}`} />
                        <span className="text-[9px] font-black uppercase text-slate-400 tracking-wider truncate">
                            {h.day} • {h.country === 'Global' ? 'Global' : h.region}
                        </span>
                    </div>
                    <h3 className="text-sm font-bold text-slate-900 dark:text-white truncate group-hover:text-brand-600 transition-colors">
                        {h.name}
                    </h3>
                </div>

                {/* Tag */}
                <span className={`px-2 py-1 rounded text-[8px] font-black uppercase tracking-widest border ${
                    h.type === 'Optional' 
                    ? 'bg-amber-50 text-amber-600 border-amber-100 dark:bg-amber-500/10 dark:text-amber-500 dark:border-amber-500/20' 
                    : 'bg-slate-50 text-slate-500 border-slate-100 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700'
                }`}>
                    {h.type === 'Optional' ? 'Opt' : 'Pub'}
                </span>
            </div>
        )) : (
            <div className="col-span-full py-12 text-center border border-dashed border-slate-200 dark:border-slate-800 rounded-xl">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">No holidays found.</p>
                <button 
                    onClick={() => { setCountry('All'); setRegion('All'); setType('All'); }}
                    className="mt-2 text-xs text-brand-600 font-bold hover:underline"
                >
                    Clear Filters
                </button>
            </div>
        )}
      </div>
    </div>
  );
}

/* --- COMPONENT: COMPACT SELECT --- */
const CompactSelect = ({ label, value, onChange, options, disabled, icon }: any) => (
    <div className={`relative bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-lg h-[38px] min-w-[140px] flex items-center ${disabled ? 'opacity-50 pointer-events-none' : ''}`}>
        <div className="absolute left-3 text-slate-400 pointer-events-none">
            {icon}
        </div>
        <select 
            value={value}
            onChange={(e) => onChange(e.target.value)}
            disabled={disabled}
            className="w-full h-full bg-transparent pl-8 pr-8 text-[10px] font-bold uppercase tracking-widest text-slate-700 dark:text-slate-200 outline-none cursor-pointer appearance-none rounded-lg hover:bg-slate-50 dark:hover:bg-white/5 transition-colors"
        >
            {options.map((opt: string) => <option key={opt} value={opt}>{opt}</option>)}
        </select>
        <ChevronDown size={12} className="absolute right-3 text-slate-300 pointer-events-none" />
    </div>
);